import { pgSchema, text, timestamp, uuid } from "drizzle-orm/pg-core";
import { v7 as uuidv7 } from "uuid";
// Generated by Better Auth CLI. Adjust the path/export name to match your project.
import { user } from "./auth";

/** Postgres schemas: hard separation between our admin data and tenant data. */
export const platformSchema = pgSchema("platform"); // app-admin (us) only
export const tenantSchema = pgSchema("tenant"); // application data, RLS-protected

/** UUIDv7 primary key, generated in the app (time-sortable). */
export const pk = () =>
  uuid("id")
    .primaryKey()
    .$defaultFn(() => uuidv7());

/** Owner tenant for tenant-scoped rows. FK is added per table (composite where needed). */
export const tenantIdCol = () => uuid("tenant_id").notNull();

/**
 * created_/updated_ columns. updated_at / updated_by are also maintained by a DB trigger
 * (see 0001_audit_rls.sql) so changes made outside the backend stay audited.
 */
export const auditColumns = () => ({
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
  createdBy: text("created_by").references(() => user.id, {
    onDelete: "set null",
  }),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
  updatedBy: text("updated_by").references(() => user.id, {
    onDelete: "set null",
  }),
});

/**
 * Replaces deleted_at. effective_end_date IS NULL = active row.
 * effective_end_date set to a date = ended / deleted.
 * Unique indexes on "current" rows use WHERE effective_end_date IS NULL.
 */
export const effectiveDates = () => ({
  effectiveEndDate: timestamp("effective_end_date", { withTimezone: true }),
});
